import{_ as t,o,c as r,ag as a}from"./chunks/framework.BSwSpTvy.js";const s="/zed-custom/demo-remember.gif",i="/zed-custom/demo-recall.gif",y=JSON.parse('{"title":"🧠 Agent Long-Term Memory System","description":"","frontmatter":{},"headers":[],"relativePath":"features/memory.md","filePath":"features/memory.md"}'),n={name:"features/memory.md"};function l(m,e,c,d,h,u){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="🧠-agent-long-term-memory-system" tabindex="-1">🧠 Agent Long-Term Memory System <a class="header-anchor" href="#🧠-agent-long-term-memory-system" aria-label="Permalink to &quot;🧠 Agent Long-Term Memory System&quot;">​</a></h1><p>The most significant upgrade to this Zed fork is the deeply integrated, persistent SQLite memory database. Most AI coding assistants suffer from &quot;amnesia&quot; between editor restarts, forcing developers to re-explain their architectural constraints, internal libraries, and known issues every single day.</p><p>We solved this.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>The agent uses two primitive tools: <code>@remember</code> and <code>@recall</code>.</p><h3 id="_1-the-remember-tool" tabindex="-1">1. The <code>@remember</code> Tool <a class="header-anchor" href="#_1-the-remember-tool" aria-label="Permalink to &quot;1. The `@remember` Tool&quot;">​</a></h3><p>When you make a significant design decision or figure out a tricky bug, you can tell the agent to remember it. The agent will categorize the memory (e.g., <em>Architecture</em>, <em>Patterns</em>, <em>Issues</em>, <em>Procedures</em>, or <em>Notes</em>) and record it in a local database scoped entirely to your current project.</p><p><img src="'+s+'" alt="Remember Tool Demo"></p><h3 id="_2-the-recall-tool" tabindex="-1">2. The <code>@recall</code> Tool <a class="header-anchor" href="#_2-the-recall-tool" aria-label="Permalink to &quot;2. The `@recall` Tool&quot;">​</a></h3><p>When you start a new session, you don&#39;t need to feed it 50 files of context. Simply ask a question, and the agent will use the <code>@recall</code> tool to retrieve exactly what you saved previously—whether it was yesterday or six months ago.</p><p><img src="'+i+'" alt="Recall Tool Demo"></p><h3 id="privacy-first" tabindex="-1">Privacy First <a class="header-anchor" href="#privacy-first" aria-label="Permalink to &quot;Privacy First&quot;">​</a></h3><p>Because this is built on SQLite directly into the Zed binary, your memories are stored purely on your local file system (<code>~/.local/share/zed/...</code>). No embeddings are sent to third parties for storage, and you retain 100% control over the context database.</p>',13)])])}const g=t(n,[["render",l]]);export{y as __pageData,g as default};
